def case_page(c):
    k = c["kpi"]
    fn = c.get("fn", False)
    parts = [hero([("Главная", "/"), ("Кейсы", "/cases"), (c["crumb"], None)], c["eyebrow"], c["h1"], c["lead"], meta=c["meta"], fn=fn, active="cases")]
    parts.append(kpi("Результаты в цифрах", k["sub"], k.get("hero"), k.get("tiles", []), k.get("scale", []), k.get("note", ""), fn=fn))
    parts.append(two_panel("Задача и что вошло в работу", "Клиент и задачи", c["left_lead"], c["tasks"], "Что сделали", c["right_lead"], c["scope"], fn=fn))
    if c["steps"]:
        parts.append(steps("Как мы это сделали", c["steps"], fn=fn, cols=2 if len(c["steps"]) == 4 else 3))
    if c.get("quote"):
        q = c["quote"]
        parts.append(quote(q[0], q[1], q[2], placeholder=(len(q) > 3 and q[3])))
    if c["concl"]:
        parts.append(concl("Выводы по проекту", "Что сработало в этом проекте и что мы переносим в проекты клиентов из этой отрасли.", c["concl"], fn=fn))
    parts.append(link_cards("Другие кейсы", more_for(c["more"])))
    parts.append(audit())
    parts.append(footer())
    ld = jsonld(breadcrumb_ld([("Главная", "/"), ("Кейсы", "/cases"), (c["crumb"], "/cases/" + c["slug"] + "/")]))
    return page("cases/" + c["slug"], c["title"], c["desc"], "site.css", "\n".join(parts), ld, noindex=c.get("noindex", False))
